} from "@surveybeat/domain";
import type { OrganizationId } from "@surveybeat/domain";
import type { Auth } from "better-auth";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Redacted from "effect/Redacted";

const authOrigin = "http://localhost:5173";

const authRequest = (path: string, body: unknown) =>
  new Request(`${authOrigin}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: authOrigin },
    body: JSON.stringify(body),
  });

const sessionTokenFromCookie = (header: string): string => {
  const pair = header.split(";")[0] ?? "";

  return Option.getOrElse(Option.fromNullishOr(pair.split("=").slice(1).join("=")), () => "");
};

export const betterAuthIdentityProvider = (params: {
  readonly auth: Pick<Auth, "api" | "handler">;
  readonly chosenOrganization: (
    sessionId: SessionId,
  ) => Effect.Effect<Option.Option<OrganizationId>, AuthUnavailable>;
  readonly rememberOrganization: (
    sessionId: SessionId,
    organizationId: OrganizationId,
  ) => Effect.Effect<void, AuthUnavailable>;
  readonly deleteSession: (sessionId: SessionId) => Effect.Effect<void, AuthUnavailable>;
}) =>
  SessionIdentityProvider.of({
    authenticate: (cookie) =>
      Effect.tryPromise({
        try: () =>
          params.auth.api.getSession({
            headers: new Headers({ cookie: `${SESSION_COOKIE}=${Redacted.value(cookie)}` }),
          }),
        catch: () => new AuthUnavailable(),
      }).pipe(
        Effect.flatMap((session) =>
          session === null
            ? Effect.fail(new Unauthenticated())
            : Effect.succeed({
                identity: identityOf(
                  AuthUserId.make(session.user.id),
                  session.user.email,
                  session.user.emailVerified,
                ),
                sessionId: SessionId.make(session.session.id),
              }),
        ),
      ),

    chosenOrganization: (sessionId) => params.chosenOrganization(sessionId),

    chooseOrganization: (sessionId, organizationId) => params.rememberOrganization(sessionId, organizationId),

    sendSignInCode: (email) =>
      Effect.tryPromise({
        try: () =>
          params.auth
            .handler(authRequest("/auth/email-otp/send-verification-otp", { email, type: "sign-in" }))
            .then((response) => {
              if (!response.ok) {
                throw new Error(`send-verification-otp answered ${response.status}`);
              }

              return response;
            }),
        catch: () => new AuthUnavailable(),
      }).pipe(Effect.asVoid),

    verifySignInCode: (email, code) =>
      Effect.tryPromise({
        try: () =>
          params.auth
            .handler(authRequest("/auth/sign-in/email-otp", { email, otp: code }))
            .then((response) =>
              response.ok
                ? Option.map(Option.fromNullishOr(response.headers.get("set-cookie")), sessionTokenFromCookie)
                : Option.none<string>(),
            ),
        catch: () => new AuthUnavailable(),
      }),

    revokeSession: (sessionId) => params.deleteSession(sessionId),
  });
import type * as Cloudflare from "@alchemy.run/cloudflare";
import {
  AuthUserId,
  EmailAddress,
  normaliseEmail,
  OrganizationId,
  PeopleIndex,
  PersonId,
} from "@surveybeat/domain";
import type { ClaimStatus, PersonCandidate } from "@surveybeat/domain";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

const CandidateRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  person_id: PersonId,
  linked: Schema.Finite,
});

const ClaimRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  admin_person_id: PersonId,
  completed_at: Schema.NullOr(Schema.Finite),
});

const IndexedRow = Schema.Struct({ auth_user_id: Schema.NullOr(AuthUserId) });

const decodeRows = <S extends Schema.Top & { readonly DecodingServices: never }>(schema: S) =>
  Schema.decodeUnknownEffect(Schema.Array(schema));

const toCandidate = (row: typeof CandidateRow.Type): PersonCandidate => ({
  organization: { id: row.organization_id, name: row.name },
  personId: row.person_id,
  linked: row.linked === 1,
});

const toClaim = (row: typeof ClaimRow.Type): ClaimStatus => ({
  organization: { id: row.organization_id, name: row.name },
  adminPersonId: row.admin_person_id,
  completed: row.completed_at !== null,
});

export const d1PeopleIndex = (db: Cloudflare.D1.QueryDatabaseClient) =>
  Effect.gen(function* () {
    const runtime = yield* Effect.context<RuntimeContext>();

    const run = <A, E>(effect: Effect.Effect<A, E, RuntimeContext>): Effect.Effect<A> =>
      effect.pipe(Effect.provideContext(runtime), Effect.orDie);

    const all = (sql: string, ...binds: readonly unknown[]) =>
      db
        .prepare(sql)
        .bind(...binds)
        .all()
        .pipe(Effect.map((result) => result.results));

    const write = (sql: string, ...binds: readonly unknown[]) =>
      run(
        db
          .prepare(sql)
          .bind(...binds)
          .run(),
      ).pipe(Effect.asVoid);

    const claimOf = (userId: string) =>
      run(
        all(
          `SELECT organization_id, name, admin_person_id, completed_at
             FROM organization_claim WHERE auth_user_id = ?`,
          userId,
        ).pipe(Effect.flatMap(decodeRows(ClaimRow))),
      ).pipe(Effect.map((rows) => Option.map(Option.fromNullishOr(rows[0]), toClaim)));

    const hasPersons = (userId: AuthUserId) =>
      run(all("SELECT 1 AS found FROM person_index WHERE auth_user_id = ? LIMIT 1", userId)).pipe(
        Effect.map((rows) => rows.length > 0),
      );

    const accountStatements: readonly (readonly [string, number])[] = [
      ["DELETE FROM captured_email WHERE recipient = (SELECT email FROM auth_user WHERE id = ?)", 1],
      [
        `DELETE FROM auth_verification
          WHERE identifier IN (
            SELECT 'sign-in-otp-' || email FROM auth_user WHERE id = ?
            UNION ALL
            SELECT 'forget-password-otp-' || email FROM auth_user WHERE id = ?
            UNION ALL
            SELECT 'email-verification-otp-' || email FROM auth_user WHERE id = ?
            UNION ALL
            SELECT 'change-email-otp-' || id || ':' || email FROM auth_user WHERE id = ?
          )
          OR substr(identifier, 1, length('change-email-otp-' || ? || ':')) = 'change-email-otp-' || ? || ':'`,
        6,
      ],
      [
        "DELETE FROM auth_session_organization WHERE session_id IN (SELECT id FROM auth_session WHERE userId = ?)",
        1,
      ],
      ["DELETE FROM auth_session WHERE userId = ?", 1],
      ["DELETE FROM auth_account WHERE userId = ?", 1],
      ["DELETE FROM auth_passkey WHERE userId = ?", 1],
      ["DELETE FROM auth_member WHERE userId = ?", 1],
      [
        "DELETE FROM auth_invitation WHERE inviterId = ? OR email = (SELECT email FROM auth_user WHERE id = ?)",
        2,
      ],
      ["DELETE FROM organization_claim WHERE auth_user_id = ?", 1],
      ["DELETE FROM auth_user WHERE id = ?", 1],
    ];

    const deleteAccount = (userId: AuthUserId) =>
      Effect.forEach(
        accountStatements,
        ([statement, binds]) => write(statement, ...Array.from({ length: binds }, () => userId)),
        { discard: true },
      );

    return PeopleIndex.of({
      linkedPersons: (userId) =>
        run(
          all(
            `SELECT p.organization_id, o.name, p.person_id, 1 AS linked
               FROM person_index p JOIN organization_index o ON o.organization_id = p.organization_id
              WHERE p.auth_user_id = ? AND p.removed_at IS NULL
              ORDER BY p.organization_id`,
            userId,
          ).pipe(Effect.flatMap(decodeRows(CandidateRow))),
        ).pipe(Effect.map((rows) => rows.map(toCandidate))),

      unlinkedPersons: (email) =>
        run(
          all(
            `SELECT p.organization_id, o.name, p.person_id, 0 AS linked
               FROM person_index p JOIN organization_index o ON o.organization_id = p.organization_id
              WHERE p.email = ? AND p.auth_user_id IS NULL AND p.removed_at IS NULL
              ORDER BY p.organization_id`,
            normaliseEmail(email),
          ).pipe(Effect.flatMap(decodeRows(CandidateRow))),
        ).pipe(Effect.map((rows) => rows.map(toCandidate))),

      putOrganization: (organization) =>
        write(
          `INSERT INTO organization_index (organization_id, name) VALUES (?, ?)
           ON CONFLICT (organization_id) DO UPDATE SET name = excluded.name`,
          organization.id,
          organization.name,
        ),

      putPerson: (person) =>
        write(
          `INSERT INTO person_index (organization_id, person_id, email, auth_user_id) VALUES (?, ?, ?, ?)
           ON CONFLICT (organization_id, person_id) DO UPDATE SET
             auth_user_id = coalesce(auth_user_id, excluded.auth_user_id),
             removed_at = NULL`,
          person.organizationId,
          person.personId,
          EmailAddress.make(normaliseEmail(person.email)),
          Option.getOrNull(person.userId),
        ),

      removePerson: (organizationId, personId) =>
        write(
          `UPDATE person_index SET removed_at = unixepoch() * 1000
            WHERE organization_id = ? AND person_id = ? AND removed_at IS NULL`,
          organizationId,
          personId,
        ),

      erasePerson: (erased) =>
        Effect.gen(function* () {
          const { organizationId, personId } = erased;

          const indexed = yield* run(
            all(
              "SELECT auth_user_id FROM person_index WHERE organization_id = ? AND person_id = ?",
              organizationId,
              personId,
            ).pipe(Effect.flatMap(decodeRows(IndexedRow))),
          );

          const userId = Option.orElse(erased.userId, () => Option.fromNullishOr(indexed[0]?.auth_user_id));

          const sendIds = JSON.stringify(erased.sendIds);
          const testTokenHashes = JSON.stringify(erased.testTokenHashes);

          yield* write(
            "DELETE FROM invitation_index WHERE organization_id = ? AND person_id = ?",
            organizationId,
            personId,
          );
          yield* write(
            `DELETE FROM test_invitation_index
              WHERE organization_id = ? AND token_hash IN (SELECT value FROM json_each(?))`,
            organizationId,
            testTokenHashes,
          );
          yield* write(
            `DELETE FROM captured_email WHERE message_id IN (
               SELECT message_id FROM email_message
                WHERE organization_id = ? AND send_id IN (SELECT value FROM json_each(?)))`,
            organizationId,
            sendIds,
          );
          yield* write(
            "DELETE FROM email_message WHERE organization_id = ? AND send_id IN (SELECT value FROM json_each(?))",
            organizationId,
            sendIds,
          );
          yield* write(
            "DELETE FROM person_index WHERE organization_id = ? AND person_id = ?",
            organizationId,
            personId,
          );

          if (Option.isNone(userId)) {
            return;
          }

          yield* write(
            `DELETE FROM auth_session_organization
              WHERE organization_id = ? AND session_id IN (SELECT id FROM auth_session WHERE userId = ?)`,
            organizationId,
            userId.value,
          );
          yield* write(
            "DELETE FROM organization_claim WHERE auth_user_id = ? AND organization_id = ?",
            userId.value,
            organizationId,
          );

          if (!(yield* hasPersons(userId.value))) {
            yield* deleteAccount(userId.value);
          }
        }),

      eraseAccount: (userId) =>
        Effect.gen(function* () {
          if (yield* hasPersons(userId)) {
            return false;
          }

          yield* deleteAccount(userId);

          return true;
        }),

      linkPerson: (organizationId, personId, userId) =>
        write(
          `UPDATE person_index SET auth_user_id = ?
            WHERE organization_id = ? AND person_id = ? AND auth_user_id IS NULL AND removed_at IS NULL`,
          userId,
          organizationId,
          personId,
        ),

      claimOrganization: (userId, proposed) =>
        write(
          `INSERT INTO organization_claim (auth_user_id, organization_id, name, admin_person_id)
           VALUES (?, ?, ?, ?) ON CONFLICT (auth_user_id) DO NOTHING`,
          userId,
          proposed.organization.id,
          proposed.organization.name,
          proposed.adminPersonId,
        ).pipe(
          Effect.andThen(claimOf(userId)),
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.die("organization_claim row vanished after insert"),
              onSome: Effect.succeed,
            }),
          ),
        ),

      claimOf,

      completeClaim: (userId, now) =>
        write(
          "UPDATE organization_claim SET completed_at = ? WHERE auth_user_id = ? AND completed_at IS NULL",
          now,
          userId,
        ),
    });
  });

import type { SqliteClient } from "@effect/sql-sqlite-do";
import {
  decide,
  DEFAULT_LOCALE,
  localeOr,
  localeOrNull,
  settingsView,
  teamsView,
  teamView,
} from "@surveybeat/domain";
import type { PersonId, TeamId, CommandResult, DirectoryCommand, FollowUp } from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import type { makeSqlDirectory } from "../SqlDirectory.ts";
import { erasePersonRows } from "./PersonErasure.ts";
import type { makeSqlRounds } from "../SqlRounds.ts";

export const organizationDirectory = ({
  sql,
  rounds,
  directory,
}: {
  sql: SqliteClient.SqliteClient;
  rounds: ReturnType<typeof makeSqlRounds>;
  directory: ReturnType<typeof makeSqlDirectory>;
}) => {
  const withErasedRows = (followUp: FollowUp): Effect.Effect<FollowUp> =>
    followUp._tag === "ErasePersonIndex"
      ? Effect.map(erasePersonRows(sql, followUp.person), (erased) => ({ ...followUp, ...erased }))
      : Effect.succeed(followUp);

  const deleteTestSendsForPerson = (personId: PersonId) =>
    sql`DELETE FROM test_send WHERE person_id = ${personId}`.pipe(Effect.asVoid, Effect.orDie);

  return {
    create: (id: string, name: string) =>
      sql
        .withTransaction(sql`INSERT INTO organization (id, name) VALUES (${id}, ${name})`)
        .pipe(Effect.as({ id, name }), Effect.orDie),

    createWithAdmin: (id: string, name: string, personId: string, email: string, authUserId: string) =>
      sql
        .withTransaction(
          Effect.all([
            sql`INSERT INTO organization (id, name) VALUES (${id}, ${name}) ON CONFLICT (id) DO NOTHING`,
            sql`INSERT INTO person (id, email, auth_user_id, organization_admin)
              VALUES (${personId}, ${email}, ${authUserId}, 1)
              ON CONFLICT (id) DO NOTHING`,
          ]),
        )
        .pipe(Effect.asVoid, Effect.orDie),

    linkPerson: (personId: string, authUserId: string, email: string) =>
      sql
        .withTransaction(
          Effect.gen(function* () {
            const other = yield* sql<{ id: string }>`
            SELECT id FROM person WHERE auth_user_id = ${authUserId} AND id <> ${personId}`;

            if (other.length > 0) {
              return false;
            }

            yield* sql`
            UPDATE person SET auth_user_id = ${authUserId}
             WHERE id = ${personId} AND email = ${email} AND removed_at IS NULL AND auth_user_id IS NULL`;

            const linked = yield* sql<{ id: string }>`
            SELECT id FROM person
             WHERE id = ${personId} AND auth_user_id = ${authUserId} AND removed_at IS NULL`;

            return linked.length > 0;
          }),
        )
        .pipe(Effect.orDie),

    activePerson: (authUserId: string) =>
      sql<{
        id: string;
        organization_admin: number;
        locale: string | null;
        detected_locale: string | null;
        default_locale: string | null;
      }>`
      SELECT person.id, person.organization_admin, person.locale, person.detected_locale,
             (SELECT default_locale FROM organization LIMIT 1) AS default_locale
        FROM person
       WHERE person.auth_user_id = ${authUserId} AND person.removed_at IS NULL`.pipe(
        Effect.map((rows) => {
          const row = rows[0];

          if (row === undefined) {
            return null;
          }

          return {
            id: row.id,
            organizationAdmin: row.organization_admin === 1,
            locale: localeOrNull(row.locale),
            detectedLocale: localeOrNull(row.detected_locale),
            organizationLocale: localeOr(row.default_locale, DEFAULT_LOCALE),
          };
        }),
        Effect.orDie,
      ),

    runDirectoryCommand: (actorId: PersonId, command: DirectoryCommand, now: number) =>
      sql
        .withTransaction(
          Effect.gen(function* () {
            const decision = decide(yield* directory.load, actorId, command, now);

            if (decision._tag === "Rejected") {
              return decision satisfies CommandResult;
            }

            yield* directory.apply(decision.changes);

            if (command._tag === "RemovePerson") {
              yield* rounds.revokeInvitationForPerson(command.personId, now);
              yield* rounds.deleteParticipationForPerson(command.personId);
              yield* deleteTestSendsForPerson(command.personId);
            }

            const followUps = yield* Effect.forEach(decision.followUps, withErasedRows);

            return {
              _tag: "Accepted",
              followUps,
            } satisfies CommandResult;
          }),
        )
        .pipe(Effect.orDie),

    clearPersonErasure: (personId: PersonId) =>
      sql`DELETE FROM person_erasure WHERE person_id = ${personId}`.pipe(Effect.asVoid, Effect.orDie),
    viewTeams: (actorId: PersonId) =>
      Effect.gen(function* () {
        const view = teamsView(yield* directory.load, actorId);

        if (view._tag !== "Viewed") {
          return view;
        }

        const nextRoundDates = yield* rounds.nextRoundDates();

        return {
          _tag: "Viewed" as const,
          value: view.value.map((team) => ({
            ...team,
            nextRoundDate: nextRoundDates[team.id] ?? null,
          })),
        };
      }),
    viewTeam: (actorId: PersonId, teamId: TeamId) =>
      directory.load.pipe(Effect.map((state) => teamView(state, actorId, teamId))),
    viewSettings: (actorId: PersonId) =>
      directory.load.pipe(Effect.map((state) => settingsView(state, actorId))),

    get: (id: string) =>
      sql<{ id: string; name: string }>`SELECT id, name FROM organization WHERE id = ${id}`.pipe(
        Effect.map((rows) => rows[0] ?? null),
        Effect.orDie,
      ),
  };
};
