};

const teamIdOf = (body: unknown): string => {
  if (typeof body === "object" && body !== null && "team" in body) {
    const { team } = body;

    if (typeof team === "object" && team !== null && "id" in team && typeof team.id === "string") {
      return team.id;
    }
  }

  throw new Error("no Team in the response");
};

