  state: {
    readonly settings: LoadedSettings;
    readonly failedEmails: LoadedFailedEmails;
    readonly failedEmailResends: Readonly<Record<string, FailedEmailResend>>;
    readonly size: string;
    readonly sizeSaved: boolean;
