        },
      };
    }

    case "EmailChangeOtherAddress": {
      return {
        model: {
          ...model,
          emailChange: { ...model.emailChange, step: "address", code: "", busy: false, failure: Option.none() },
        },
      };
    }

    case "EmailChangeDismissed": {
      return {
        model: {
          ...model,
          emailChange: { step: "closed", email: "", code: "", busy: false, failure: Option.none() },
        },
      };
    }

